function possibleOriginals(word: string): number {
  const seen = new Set<string>([word]);
  let i = 0;
  while (i < word.length) {
    let j = i;
    while (j < word.length && word[j] === word[i]) j++;
    for (let keep = 1; keep < j - i; keep++) seen.add(word.slice(0, i + keep) + word.slice(j));
    i = j;
  }
  return seen.size;
}

