class Solution:
    def possibleOriginals(self, word: str) -> int:
        seen = {word}
        i = 0
        while i < len(word):
            j = i
            while j < len(word) and word[j] == word[i]:
                j += 1
            for keep in range(1, j - i):
                seen.add(word[:i + keep] + word[j:])
            i = j
        return len(seen)

